import{_ as t,l as n,o as a,c as i,v as o,p as l,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"DeepSeek V4","description":"","frontmatter":{"title":"DeepSeek V4","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deepseek-v4.md","filePath":"llm/deepseek-v4.md","lastUpdated":1789023840000}'),A={name:"llm/deepseek-v4.md"};function E(c,e,m,B,P,k){const s=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="deepseek-v4" tabindex="-1">DeepSeek V4 <a class="header-anchor" href="#deepseek-v4" aria-label="Permalink to &quot;DeepSeek V4&quot;">​</a></h1><div class="epigraph"><p>在百万上下文设定下，V4-Pro 相对 V3.2 只需约 27% 的单 token 推理 FLOPs 与 10% 的 KV；把超长上下文做成可日常服务的默认，而不是演示开关。</p><footer>—— DeepSeek-AI，DeepSeek-V4: Towards Highly Efficient Million-Token Context Intelligence，arXiv:2606.19348</footer></div><p><a href="/llm/deepseek-v3">DeepSeek-V3</a> 把细粒度 MoE 与 MTP 做成开源旗舰骨架；V3.2 把 <a href="/llm/deepseek-sparse-attention">DSA</a> 接到长上下文。2026 年 4 月 24 日的 <strong>DeepSeek-V4 Preview</strong> 把目标改成「买得起的 1M 窗口」：同时开源 <strong>V4-Pro</strong>（1.6T 总量 / <strong>49B</strong> 激活）与 <strong>V4-Flash</strong>（284B / <strong>13B</strong> 激活），官方服务默认 1M。技术报告 arXiv:2606.19348 写明混合注意力 <strong>CSA + HCA</strong>、流形约束超连接 <strong>mHC</strong>、以及 <strong>Muon</strong> 优化器。2026 年 8 月 13 日左右的 <strong>V4-Pro-0813</strong> 被写成取代预览的正式档，强化智能体。本篇以预览报告与官网新闻为骨架，正式档的价目与 DSpark 以当时公告为准，不把未写入报告的层宽表从二手文抄来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>推理模型把测试时计算当成第二缩放轴，但标准注意力对超长序列是二次的。智能体轨迹、跨文档分析、Think Max 所需的超长思维，会先被 KV 与 FLOPs 卡住，而不是被「不会想」卡住。V3.2 已经用 DSA 降长上下文费用；V4 要回答的是：能否让 <strong>1M 成为所有官方服务的默认</strong>，并且 Pro 在 1M 上仍只有 V3.2 大约四分之一的单 token 计算、十分之一的 KV。</p><p>第二个问题是后训练如何在数学、代码、智能体、指令上分别变强，再收成用户看见的一个检查点。V3 式「一个混合推理模型」仍然成立，但专家要先分域养成。</p><h3 id="pro-与-flash-是两条激活曲线-不是两个窗口档" tabindex="-1">Pro 与 Flash 是两条激活曲线，不是两个窗口档 <a class="header-anchor" href="#pro-与-flash-是两条激活曲线-不是两个窗口档" aria-label="Permalink to &quot;Pro 与 Flash 是两条激活曲线，不是两个窗口档&quot;">​</a></h3><p>官网同一天放出两档，窗口都是 1M，都支持思考 / 非思考。Pro 打的是智能体编码、世界知识与数理代码的开源上限；Flash 打的是接近 Pro 的推理、更小激活、更快响应。报告：Flash 预训约 <strong>32T</strong> token，Pro 约 <strong>33T</strong>。Think Max 是 Pro 上的最大推理力度，不是另一个权重文件的别名。预览 API 名 <code>deepseek-v4-pro</code> / <code>deepseek-v4-flash</code>；旧的 <code>deepseek-chat</code> / <code>deepseek-reasoner</code> 曾映射到 Flash 的非思考 / 思考，并计划在 2026-07-24 后退役。</p><p><span class="marginnote">1M 上下文上 Pro 相对 V3.2：约 27% 单 token FLOPs（按等价 FP8）、10% KV；Flash 进一步到约 10% FLOPs、7% KV。专家权重走 FP4，现有硬件上 FP4×FP8 峰值往往仍等于 FP8×FP8，报告把更大的效率留给未来器件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>骨架仍是 Transformer + DeepSeekMoE + 与 V3 相同的 MTP。MoE 亲和度从 Sigmoid 换成 \\(\\sqrt{\\mathrm{softplus}(\\cdot)}\\)；无辅助损失的平衡仍在，并加轻微序列级平衡以免单条序列极端倾斜。去掉路由目标节点数限制；最初若干块的稠密 FFN 改成按 token ID <strong>哈希路由</strong>的 MoE。这些是报告写明的「小改」；大改在注意力与残差。</p><h3 id="csa-hca-与-mhc" tabindex="-1">CSA / HCA 与 mHC <a class="header-anchor" href="#csa-hca-与-mhc" aria-label="Permalink to &quot;CSA / HCA 与 mHC&quot;">​</a></h3><p>**CSA（Compressed Sparse Attention）**先沿序列压缩 KV，再跑 DSA。**HCA（Heavily Compressed Attention）**把 KV 压得更狠，但注意力保持稠密。二者混排，用来换长上下文的 FLOPs 与缓存。<strong>mHC</strong> 把残差流扩宽 \\(n_{\\mathrm{hc}}\\) 倍，但把残差映射 \\(B_l\\) 约束到双随机矩阵（Birkhoff 多面体）上：行和列和为 1、非负，谱范数 \\(\\le 1\\)，深层连乘仍稳定。无约束的 Hyper-Connection 在深堆上会数值炸；Sinkhorn–Knopp 把原始 \\(B\\) 投影回该流形。输入 / 输出映射用 Sigmoid 保证非负有界。优化器改 <strong>Muon</strong>，换更快收敛与更稳的万亿 MoE。</p>',13)),(a(),l(h,null,{default:r(()=>[d(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%AE%8B%E5%B7%AE%E6%B5%81%EF%BC%88mHC%20%E6%89%A9%E5%AE%BD%EF%BC%89%22%5D%20--%3E%20ATT%5B%22%E6%B7%B7%E5%90%88%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20ATT%20--%3E%20CSA%5B%22CSA%EF%BC%9A%E5%8E%8B%E7%BC%A9%20KV%20%2B%20DSA%22%5D%0A%20%20ATT%20--%3E%20HCA%5B%22HCA%EF%BC%9A%E6%9B%B4%E7%8B%A0%E5%8E%8B%E7%BC%A9%20%2B%20%E7%A8%A0%E5%AF%86%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20CSA%20--%3E%20FFN%5B%22DeepSeekMoE%22%5D%0A%20%20HCA%20--%3E%20FFN%0A%20%20FFN%20--%3E%20MTP%5B%22MTP%20%E6%8A%95%E6%9C%BA%E5%A4%B4%22%5D%0A%20%20PRE%5B%2232%E2%80%9333T%20%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%20--%3E%20BASE%5B%22Pro%20%2F%20Flash%20Base%22%5D%0A%20%20BASE%20--%3E%20EXP%5B%22%E5%88%86%E5%9F%9F%20SFT%20%2B%20GRPO%20%E4%B8%93%E5%AE%B6%22%5D%0A%20%20EXP%20--%3E%20DIST%5B%22On-policy%20%E8%92%B8%E9%A6%8F%E6%88%90%E7%BB%9F%E4%B8%80%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>后训练两段：各域（数学、代码、智能体、指令）先 SFT 再 GRPO，得到专家；再用 on-policy 蒸馏、反向 KL，把能力收进一个统一模型。后训练对 MoE 专家与 indexer 的 QK 路径做 FP4 量化感知训练。推理侧设计异构 KV 与落盘策略，以便共享前缀复用。</p><p><span class="marginnote">Think Max 需要足够长的上下文预算（社区文档常写至少约 384K 量级，以当时 API 指南为准）。采样推荐温度 1.0、top-p 1.0。预览与 0813 正式档的智能体分数不是同一行，引用要写检查点名。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CSA 把「先稀疏再算」接到压缩后的序列轴上，长度带来的二次项作用在更短的压缩长度上；HCA 用更小的 KV 换一层仍能精确归一化的稠密注意力，避免全程稀疏把针检索打穿。二者必须混用：只有 DSA 会在某些全局依赖上丢分，只有重度压缩稠密层则算不过来。mHC 提供一条几乎不增加层内 FLOPs 的宽度轴——真正算子仍吃 \\(d\\) 维，扩的是残差流。双随机约束保证这一宽度轴不会变成深层放大系数。</p><p>Muon 替代 Adam 系，与 K2 的故事同类：正交化更新换 token 效率，稳定训练是前提。分域专家再蒸馏，避免单一 RL 奖励把数学文风写进办公智能体。Flash 知识容量小于 Pro，但在更大思考预算下推理可以接近；难智能体仍是 Pro 的主场。</p><h3 id="预览与正式档" tabindex="-1">预览与正式档 <a class="header-anchor" href="#预览与正式档" aria-label="Permalink to &quot;预览与正式档&quot;">​</a></h3><p>4 月预览把 1M 做成默认并开源权重。8 月 GA（V4-Pro-0813）官方强调智能体能力与 Responses API / Codex 集成，思考力度扩到 low / high / max；价目随后按峰谷调整，<strong>具体数字以当时定价页为准</strong>，不要把预览期的 0.87 美元 / M 输出写成永恒。DSpark 一类投机模块若出现在 GA 说明里，是服务侧附件，不是报告里 CSA 公式的一部分。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>报告是 <strong>preview</strong> 版本的架构与训练叙述；0813 的智能体增益来自后训练与产品集成，未必改 CSA/HCA 公式。哈希路由只用于最前若干 MoE 层，不要写成全程。mHC 的 \\(n_{\\mathrm{hc}}\\) 具体整数以报告表格为准，未引用原表就不要填。权重在 Hugging Face <code>deepseek-ai/deepseek-v4</code> 集合；许可以仓库为准（社区常写 MIT，仍以 LICENSE 文件为准）。V4 官方新闻强调文本智能体与长上下文，不要把未写入报告的原生视频生成写进本篇。</p><p>1M 默认改变的是账单形状：缓存未命中时输入价仍按百万计。把整仓无压缩塞进窗口，先打的是钱。Think 与 Non-Think 混评没有意义。</p><p><span class="marginnote">出处：DeepSeek，<em>DeepSeek-V4 Preview</em> 官网新闻（2026-04-24）；DeepSeek-AI，arXiv:2606.19348。GA 检查点以 2026-08 官方公告为准。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>V4-Pro 1.6T/49B、V4-Flash 284B/13B，官方默认 1M 上下文；预训约 32–33T token。</li><li>混合 CSA+HCA 降长上下文 FLOPs 与 KV；mHC 约束残差；优化器 Muon；MoE/MTP 承 V3。</li><li>后训练先分域专家再 on-policy 蒸馏；Think / Non-Think 与 Max 力度是解码制度。</li><li>预览与 0813 正式档要分开引用；价目会变。</li><li>出处：官网新闻与 arXiv:2606.19348。</li></ul>',13))])}const C=t(A,[["render",E]]);export{g as __pageData,C as default};
